{
  "statements": [
    {
      "id": "1a",
      "type": "DEFINE",
      "force": null,
      "force_from": null,
      "text": "DEFINE passing IS a lane change THAT moves past a slower vehicle ALSO CALLED overtaking",
      "sources": [
        {
          "id": "m1",
          "quote": "Changing your position on the road involves changing lanes or overtaking and passing another vehicle."
        },
        {
          "id": "m2",
          "quote": "Passing is changing lanes to move past a slower vehicle."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "1b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT not all vehicles travel at the same speed, so a driver may want to pass some slow-moving vehicles WHEN the driver is following them",
      "sources": [
        {
          "id": "m3",
          "quote": "While all public roads have speed limits, not all vehicles travel at the same speed. For example, cyclists, road service vehicles and drivers ahead that are preparing to turn are usually slower than the through traffic. You may want to pass some slow-moving vehicles when you are following them."
        }
      ],
      "flags": [],
      "links": [],
      "note": "\"May want to\" is a possibility, not a permission, so this is a FACT."
    },
    {
      "id": "2.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"be sure\")",
      "text": "a driver SHOULD be sure the driver has [?enough space and time] to complete the move [?safely] WHEN the driver is about to change lanes or pass another vehicle",
      "sources": [
        {
          "id": "m4",
          "quote": "Before beginning, be sure you have enough space and time to complete the move safely."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough space and time",
          "note": "No measure of space or time."
        },
        {
          "code": "J",
          "span": "safely",
          "note": "Subjective safety; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.1b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Never\")",
      "text": "a driver SHOULD NOT pass another vehicle UNLESS the driver is [?sure] the driver can do so without danger to the driver or others",
      "sources": [
        {
          "id": "m5",
          "quote": "Never overtake and pass another vehicle unless you are sure you can do so without danger to yourself or others."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "sure",
          "note": "Subjective certainty; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.1c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not pass\")",
      "text": "a driver SHOULD NOT pass another vehicle WHEN the driver is in doubt",
      "sources": [
        {
          "id": "m6",
          "quote": "If in doubt, do not pass."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "in doubt",
          "note": "Subjective state; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.2a",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO pass a vehicle",
      "steps": [
        {
          "n": "1",
          "text": "use the left-turn signal to show that the driver wants to pass AND check that the way is clear ahead and behind WHEN the driver is about to move into the passing lane",
          "sources": [
            "m9"
          ]
        },
        {
          "n": "2",
          "text": "change lanes ONLY IF the driver has signalled",
          "sources": [
            "m11"
          ]
        },
        {
          "n": "3",
          "text": "signal that the driver wants to move back into the original lane AND change lanes WHEN the driver can see the entire front of the vehicle being passed in the inside mirror",
          "sources": [
            "m11"
          ]
        }
      ],
      "sources": [
        {
          "id": "m8",
          "quote": "Here are the steps for passing a vehicle:"
        },
        {
          "id": "m14",
          "quote": "how to pass another vehicle"
        }
      ],
      "flags": [
        {
          "code": "V",
          "span": "inside mirror",
          "note": "Handbook uses 'inside mirror' here and 'rear view mirror' in m43."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "2.2b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"Watch for\")",
      "text": "a driver SHOULD WATCH FOR bicycles and small vehicles that may be hidden from view in front of the vehicle being passed AND vehicles that may be turning left in front of the driver AND vehicles or pedestrians entering the road from another road or driveway WHILE passing a vehicle",
      "sources": [
        {
          "id": "m10",
          "quote": "Watch for bicycles and small vehicles that may be hidden from view in front of the vehicle you are about to pass. Also watch for vehicles that may be turning left in front of you and vehicles or pedestrians entering the road from another road or driveway."
        }
      ],
      "flags": [],
      "links": [
        "2.2a"
      ],
      "note": null
    },
    {
      "id": "2.2c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"Be careful\")",
      "text": "a driver SHOULD NOT cut off a vehicle by suddenly moving in front of it WHILE passing a vehicle",
      "sources": [
        {
          "id": "m12",
          "quote": "Be careful not to cut off a vehicle by suddenly moving in front of it."
        }
      ],
      "flags": [],
      "links": [
        "2.2a"
      ],
      "note": null
    },
    {
      "id": "2.2d",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"do not race\", \"Go back\")",
      "text": "a driver SHOULD NOT race AND SHOULD go back to the original lane WHEN the vehicle being passed speeds up",
      "sources": [
        {
          "id": "m13",
          "quote": "If the vehicle you are passing speeds up, do not race. Go back to your original lane."
        }
      ],
      "flags": [],
      "links": [
        "2.2a"
      ],
      "note": null
    },
    {
      "id": "3.1.1a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not permitted\")",
      "text": "a driver MUST NOT pass a vehicle WHEN the driver is within 30 m of a pedestrian crossover",
      "sources": [
        {
          "id": "m15",
          "quote": "Passing within 30 metres of a pedestrian crossover is not permitted."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.1.2a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not permitted\")",
      "text": "a driver MUST NOT pass left of a centreline WHEN the driver is within 30 m of a bridge, viaduct or tunnel",
      "sources": [
        {
          "id": "m17",
          "quote": "Passing left of a centreline is not permitted 30 metres from a bridge, viaduct or tunnel."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.1.3a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't attempt\")",
      "text": "a driver SHOULD NOT attempt to pass WHEN the driver is approaching the crest of a hill OR the driver is on a curve AND the driver's vision of oncoming traffic is obstructed AND there is not [?enough clear distance] ahead to pass in [?safety]",
      "sources": [
        {
          "id": "m18",
          "quote": "Don't attempt to pass when approaching the crest of a hill or on a curve where your vision of oncoming traffic is obstructed and there is not enough clear distance ahead to pass in safety."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "enough clear distance",
          "note": "No measure of distance."
        },
        {
          "code": "J",
          "span": "safety",
          "note": "Subjective safety; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.1a",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT some roads have special passing or climbing lanes that let slower vehicles move into the right-hand lane so that faster ones can pass safely in the left lane",
      "sources": [
        {
          "id": "m28",
          "quote": "Some roads have special passing or climbing lanes. These lanes let slower vehicles move into the right-hand lane so that faster ones can pass safely in the left lane."
        },
        {
          "id": "m27",
          "quote": "a passing or climbing lane"
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.1b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT an advance sign tells drivers they will soon have a chance to pass AND another sign warns when the lane is ending so drivers in the right-hand lane can begin to merge safely with traffic in the left-hand lane",
      "sources": [
        {
          "id": "m29",
          "quote": "An advance sign tells drivers they will soon have a chance to pass. Another sign warns when the lane is ending so drivers in the right-hand lane can begin to merge safely with traffic in the left-hand lane."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may\")",
      "text": "a driver MAY pass on the right WHEN the road is multi-lane OR the road is one-way OR the vehicle being passed is a streetcar OR the vehicle being passed is turning left",
      "sources": [
        {
          "id": "m35",
          "quote": "Most passing is done on the left. You may pass on the right on multi-lane or one-way roads and when overtaking a streetcar or a left-turning vehicle."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3b",
      "type": "FACT",
      "force": null,
      "force_from": null,
      "text": "FACT passing on the right can be more dangerous than passing on the left",
      "sources": [
        {
          "id": "m36",
          "quote": "Passing on the right can be more dangerous than passing on the left."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.3c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"wait\", \"Do not\")",
      "text": "a driver SHOULD wait for the vehicle in front to move to the right AND SHOULD NOT suddenly change lanes and pass on the right WHEN the driver is driving in the far-left lane AND there is a slower vehicle in front of the driver",
      "sources": [
        {
          "id": "m37",
          "quote": "If you are driving in the left most lane with a slower vehicle in front of you, wait for the vehicle to move to the right. Do not suddenly change lanes and pass on the right; the driver in front may realize you want to pass and move to the right at the same time you do."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.4a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may\")",
      "text": "a driver MAY drive on the right shoulder ONLY IF the driver is passing a vehicle turning left AND the shoulder is paved",
      "sources": [
        {
          "id": "m38",
          "quote": "You may drive on the right shoulder only to pass a vehicle turning left and only if the shoulder is paved. You may not pass on the left shoulder, paved or not."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.2.4b",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"may not\")",
      "text": "a driver MUST NOT pass on the left shoulder",
      "sources": [
        {
          "id": "m38",
          "quote": "You may drive on the right shoulder only to pass a vehicle turning left and only if the shoulder is paved. You may not pass on the left shoulder, paved or not."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.3.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"Be very careful\")",
      "text": "a driver SHOULD pass other vehicles with [?extra care] WHEN passing at night",
      "sources": [
        {
          "id": "m39",
          "quote": "Be very careful when you pass other vehicles at night."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "extra care",
          "note": "No specific hazard named; vague caution."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.3.1b",
      "type": "PROCEDURE",
      "force": "ADVISORY",
      "force_from": "imperative steps",
      "text": "TO pass a vehicle at night WHEN the driver has to pass AND the way is clear",
      "steps": [
        {
          "n": "1",
          "text": "switch the headlights to low beams WHEN the driver is approaching a vehicle from behind",
          "sources": [
            "m41"
          ]
        },
        {
          "n": "2",
          "text": "signal AND check the mirrors and blind spot AND pull out to pass",
          "sources": [
            "m42"
          ]
        },
        {
          "n": "3",
          "text": "switch on the high beams WHILE moving alongside the vehicle being passed",
          "sources": [
            "m42"
          ]
        },
        {
          "n": "4",
          "text": "pull back into the right-hand lane WHEN the driver can see all of the front of the vehicle being passed in the inside mirror",
          "sources": [
            "m43"
          ]
        },
        {
          "n": "5",
          "text": "signal",
          "sources": [
            "m43"
          ]
        }
      ],
      "sources": [
        {
          "id": "m40",
          "quote": "If you have to pass and the way is clear, follow these steps:"
        },
        {
          "id": "m52",
          "quote": "how to pass another vehicle"
        }
      ],
      "flags": [
        {
          "code": "V",
          "span": "inside mirror",
          "note": "Handbook uses 'rear view mirror' here and 'inside mirror' in m11."
        }
      ],
      "links": [
        "2.2a"
      ],
      "note": "Specializes the general passing procedure for night conditions."
    },
    {
      "id": "3.4.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "caution (\"watch carefully\")",
      "text": "a driver SHOULD WATCH FOR people suddenly opening doors AND doors opened to load and unload WHEN passing parked vehicles",
      "sources": [
        {
          "id": "m50",
          "quote": "When passing parked vehicles, watch carefully for people suddenly opening doors or for doors opened to load and unload."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"must\")",
      "text": "a driver MUST pass a streetcar on the right UNLESS the driver is driving on a one-way road",
      "sources": [
        {
          "id": "m62",
          "quote": "You must pass streetcars on the right unless you are driving on a one-way road."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5b",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"stay\")",
      "text": "a driver SHOULD stay at least 2 m behind the rear doors WHERE passengers are getting off or on WHEN the driver is at a streetcar stop UNLESS an area has been set aside for streetcar passengers at the stop",
      "sources": [
        {
          "id": "m63",
          "quote": "At streetcar stops, stay at least two metres behind the rear doors where passengers are getting off or on. This rule does not apply at stops where an area has been set aside for streetcar passengers."
        },
        {
          "id": "m61",
          "quote": "a vehicle stopped the required two metres behind the rear doors of a stopped streetcar"
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "stay at least two metres",
          "note": "Fixed distance in a bare imperative reads like a legal duty, but no legal wording is present."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.5c",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"pass\", \"be prepared\")",
      "text": "a driver SHOULD pass [?these areas] at a [?reasonable speed] AND SHOULD be prepared for pedestrians to make sudden or unexpected moves WHEN passing a streetcar stop",
      "sources": [
        {
          "id": "m64",
          "quote": "Always pass these areas at a reasonable speed and be prepared for pedestrians to make sudden or unexpected moves."
        }
      ],
      "flags": [
        {
          "code": "R",
          "span": "these areas",
          "note": "Refers to streetcar stops mentioned in the previous passage."
        },
        {
          "code": "J",
          "span": "reasonable speed",
          "note": "No measure of speed."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.9a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Don't pass\")",
      "text": "a driver SHOULD NOT pass a moving snow plow",
      "sources": [
        {
          "id": "m72",
          "quote": "Don't pass moving snow plows under any conditions."
        }
      ],
      "flags": [
        {
          "code": "M",
          "span": "under any conditions",
          "note": "Absolute prohibition with no legal wording; stays SHOULD NOT."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.6.1a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"move\")",
      "text": "a driver being passed SHOULD move to the right AND let faster traffic pass in [?safety] WHEN faster traffic wants to pass the driver",
      "sources": [
        {
          "id": "m84",
          "quote": "When faster traffic wants to pass you, move to the right and let it pass in safety."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "safety",
          "note": "Subjective safety; no observable test."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.6.2a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"pay attention\", \"move\", \"Be prepared\")",
      "text": "a driver being passed SHOULD pay attention to oncoming traffic AND SHOULD move closer to the right side of the lane AND SHOULD be prepared to slow down WHEN the driver is being passed on an undivided road AND the passing driver has pulled into the opposite lane",
      "sources": [
        {
          "id": "m89",
          "quote": "When being passed on an undivided road where the passing driver has pulled into the opposite lane, pay attention to oncoming traffic and move closer to the right side of the lane. Be prepared to slow down to let the passing driver get in front of you more quickly to prevent a collision."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.6.3a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"move\")",
      "text": "a driver SHOULD move into the right-hand lane [?as soon as the driver can] WHEN the driver is in the truck passing lane AND a truck wants to pass the driver",
      "sources": [
        {
          "id": "m90",
          "quote": "On many high-speed roads with three or more lanes in each direction, trucks are not allowed to drive in the far left-hand lane. This means that the lane next to it is the truck passing lane. If you are in this lane and a truck wants to pass, move into the right-hand lane as soon as you can."
        }
      ],
      "flags": [
        {
          "code": "J",
          "span": "as soon as the driver can",
          "note": "No measure of time or distance."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.6.3b",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"not allowed\")",
      "text": "a truck driver MUST NOT drive in the far-left lane WHEN the road is a high-speed road with three or more lanes in each direction",
      "sources": [
        {
          "id": "m90",
          "quote": "On many high-speed roads with three or more lanes in each direction, trucks are not allowed to drive in the far left-hand lane."
        }
      ],
      "flags": [
        {
          "code": "S",
          "span": "many",
          "note": "Hedged scope; not all such roads may have this rule."
        }
      ],
      "links": [],
      "note": null
    },
    {
      "id": "3.6.4a",
      "type": "RULE",
      "force": "LEGAL",
      "force_from": "text (\"unlawful\")",
      "text": "a driver being passed MUST NOT speed up WHEN another driver is trying to pass the driver",
      "sources": [
        {
          "id": "m85",
          "quote": "And do not speed up when another driver is trying to pass you. It is unlawful and dangerous."
        }
      ],
      "flags": [],
      "links": [],
      "note": null
    },
    {
      "id": "3.4.2a",
      "type": "RULE",
      "force": "ADVISORY",
      "force_from": "imperative (\"Do not take\", \"do so by changing lanes\")",
      "text": "a driver SHOULD NOT pass a motorcycle, bicycle, limited-speed motorcycle or moped in the same lane WHEN the vehicle pulls to the left or right side of its lane",
      "sources": [
        {
          "id": "m51",
          "quote": "Motorcycles, bicycles, limited-speed motorcycles and mopeds often need to pull to the left or right side of their lane to avoid dangerous road conditions or to be seen by other drivers. Do not take this as an invitation to pass in the same lane. If you do want to pass these vehicles, do so by changing lanes."
        }
      ],
      "flags": [],
      "links": [],
      "note": "The instruction 'do so by changing lanes' implies passing in the same lane is prohibited when these vehicles shift position."
    }
  ]
}
